// fits монотонна: false…false true…true, и fits(hi) == true
int MinTrue(int lo, int hi, Func<int, bool> fits) {
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (fits(mid)) hi = mid;      // mid подходит — ответ не правее
        else lo = mid + 1;            // mid мал — ответ правее
    }
    return lo;
}

