public int MySqrt(int x) {                 // наибольшее r: r * r <= x
    int lo = 0, hi = x;                    // fits(0) == true всегда
    while (lo < hi) {
        int mid = hi - (hi - lo) / 2;      // середина вверх: mid > lo
        if ((long)mid * mid <= x) lo = mid;
        else hi = mid - 1;
    }
    return lo;
}
// MySqrt(8) == 2, MySqrt(16) == 4, MySqrt(int.MaxValue) == 46340

